package fr.cercle.aplomb;import java.util.*;public class MechanicsTest{public static void main(String[] a){int n=0;for(int k=1;k<=100;k++){float v=k*5;float initial=v;for(int i=0;i<1000;i++)v=Mechanics.brake(v,.016f,300);if(v!=0)throw new AssertionError("brake must stop");n++;if(Mechanics.brake(initial,0,300)!=initial)throw new AssertionError("pause");n++;}ArrayList<float[]> b=new ArrayList<>();b.add(new float[]{360,1010,330,55});b.add(new float[]{390,955,190,55});if(!Mechanics.stable(b))throw new AssertionError("safe overhang");n++;b.add(new float[]{590,900,220,55});if(Mechanics.stable(b))throw new AssertionError("unsupported stack");n++;System.out.println(n+" physical rule checks passed");}}